-- Legacy-compatible subset of the TMS Normal Karing reward pool.
-- TMS client data has no server drop-rate table; equipment chances below are
-- BeiDou compatibility settings, not claimed TMS source probabilities.
ON DUPLICATE KEY UPDATE
    `minimum_quantity` = VALUES(`minimum_quantity`),
    `maximum_quantity` = VALUES(`maximum_quantity`),
    `questid` = VALUES(`questid`),
    `chance` = VALUES(`chance`);
